function text(value: string, field: string): string {
  const result = value.trim();
  if (result.length === 0) throw new TypeError(`${field} must not be empty`);
  return result;
}

function amount(value: number, field: string): number {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(`${field} must be finite and non-negative`);
  }
  return value;
}

export class Material {
  public readonly id: string;
  public readonly label: string;
  public unitValue: number;

  public constructor(id: string, label: string, unitValue: number) {
    this.id = text(id, "id");
    this.label = text(label, "label");
    this.unitValue = amount(unitValue, "unitValue");
  }
}

export class Container {
  public readonly id: string;
  public readonly label: string;
  public readonly material0: Material;
  public readonly material1: Material;
  public quantity0: number;
  public quantity1: number;
  public totalValue: number;

  public constructor(
    id: string,
    label: string,
    material0: Material,
    material1: Material,
    quantity0: number,
    quantity1: number,
    totalValue: number
  ) {
    this.id = text(id, "id");
    this.label = text(label, "label");
    this.material0 = material0;
    this.material1 = material1;
    this.quantity0 = amount(quantity0, "quantity0");
    this.quantity1 = amount(quantity1, "quantity1");
    this.totalValue = amount(totalValue, "totalValue");
  }
}

export class AssetRegistry {
  private readonly materials = new Map<string, Material>();
  private readonly containers = new Map<string, Container>();

  public getMaterial(id: string, label: string, unitValue: number): Material {
    const key = text(id, "id");
    const existing = this.materials.get(key);
    if (existing) return existing;
    const created = new Material(key, label, unitValue);
    this.materials.set(key, created);
    return created;
  }

  public getContainer(
    id: string,
    label: string,
    material0: Material,
    material1: Material
  ): Container {
    const key = text(id, "id");
    const existing = this.containers.get(key);
    if (existing) return existing;
    const created = new Container(key, label, material0, material1, 0, 0, 0);
    this.containers.set(key, created);
    return created;
  }
}

export function updateContainerValue(
  container: Container,
  first: Material,
  second: Material
): number {
  if (container.material0.id !== first.id || container.material1.id !== second.id) {
    throw new TypeError("materials do not match container slots");
  }
  const total =
    amount(container.quantity0, "quantity0") * amount(first.unitValue, "unitValue") +
    amount(container.quantity1, "quantity1") * amount(first.unitValue, "unitValue");
  container.totalValue = total;
  return total;
}

