import { Material, Container, AssetRegistry, updateContainerValue } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function throwsType(action: () => void, expected: "TypeError" | "RangeError", message: string): void {
  let caught: unknown;
  try { action(); } catch (error: unknown) { caught = error; }
  const valid = expected === "TypeError" ? caught instanceof TypeError : caught instanceof RangeError;
  if (!valid) throw new Error(`${message}: expected ${expected}`);
}

const steel = new Material(" steel ", " Steel ", 2.5);
assert(steel.id === "steel" && steel.label === "Steel" && steel.unitValue === 2.5, "Material trims and stores fields");
steel.unitValue = 3;
assert(steel.unitValue === 3, "unitValue is mutable");

const wood = new Material("wood", "Wood", 4);
const box = new Container(" box ", " Box ", steel, wood, 2, 3, 0);
assert(box.id === "box" && box.label === "Box", "Container trims identity fields");
assert(box.material0 === steel && box.material1 === wood, "Container retains slot materials");
assert(box.quantity0 === 2 && box.quantity1 === 3 && box.totalValue === 0, "Container stores numeric fields");
assert(updateContainerValue(box, steel, wood) === 18, "value calculation returns result");
assert(box.totalValue === 18, "value calculation updates container");

throwsType(() => new Material(" ", "Label", 1), "TypeError", "empty material id");
throwsType(() => new Material("id", " ", 1), "TypeError", "empty material label");
for (const value of [-1, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsType(() => new Material("id", "Label", value), "RangeError", "invalid unit value");
}
throwsType(() => new Container(" ", "Label", steel, wood, 0, 0, 0), "TypeError", "empty container id");
throwsType(() => new Container("id", " ", steel, wood, 0, 0, 0), "TypeError", "empty container label");
for (const value of [-1, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsType(() => new Container("id", "Label", steel, wood, value, 0, 0), "RangeError", "invalid quantity0");
  throwsType(() => new Container("id", "Label", steel, wood, 0, value, 0), "RangeError", "invalid quantity1");
  throwsType(() => new Container("id", "Label", steel, wood, 0, 0, value), "RangeError", "invalid totalValue");
}

box.quantity0 = -1;
throwsType(() => updateContainerValue(box, steel, wood), "RangeError", "update rejects negative quantity");
box.quantity0 = 2;
steel.unitValue = Number.POSITIVE_INFINITY;
throwsType(() => updateContainerValue(box, steel, wood), "RangeError", "update rejects non-finite unit value");
steel.unitValue = 3;

const impostorSteel = new Material("other", "Steel", 3);
throwsType(() => updateContainerValue(box, impostorSteel, wood), "TypeError", "first slot mismatch");
throwsType(() => updateContainerValue(box, steel, impostorSteel), "TypeError", "second slot mismatch");
assert(box.totalValue === 18, "failed updates do not replace total");

const registry = new AssetRegistry();
const canonicalMaterial = registry.getMaterial(" m1 ", "First", 7);
const repeatedMaterial = registry.getMaterial("m1", "Ignored", 99);
assert(canonicalMaterial === repeatedMaterial, "material identity is canonical by trimmed id");
assert(repeatedMaterial.label === "First" && repeatedMaterial.unitValue === 7, "later material metadata is ignored");
const m2 = registry.getMaterial("m2", "Second", 8);
const canonicalContainer = registry.getContainer(" c1 ", "Container One", canonicalMaterial, m2);
const repeatedContainer = registry.getContainer("c1", "Ignored", m2, canonicalMaterial);
assert(canonicalContainer === repeatedContainer, "container identity is canonical by trimmed id");
assert(repeatedContainer.label === "Container One", "later container metadata is ignored");
assert(repeatedContainer.material0 === canonicalMaterial && repeatedContainer.material1 === m2, "canonical slots remain unchanged");

const otherRegistry = new AssetRegistry();
const otherMaterial = otherRegistry.getMaterial("m1", "Other", 1);
assert(otherMaterial !== canonicalMaterial, "registries do not share material state");
const otherContainer = otherRegistry.getContainer("c1", "Other Container", otherMaterial, otherMaterial);
assert(otherContainer !== canonicalContainer, "registries do not share container state");

